export default {
  async fetch(req, env) {
    const u = new URL(req.url);
    const which = u.searchParams.get("b") || "A";
    const target = u.searchParams.get("t") || "http://svc/";
    const t0 = Date.now();
    try {
      const r = await env[which].fetch(target);
      const body = await r.text();
      return new Response(JSON.stringify({binding: which, target, status: r.status, ms: Date.now() - t0, body}), {headers: {"content-type": "application/json"}});
    } catch (e) {
      return new Response(JSON.stringify({binding: which, target, error: String(e), ms: Date.now() - t0}), {status: 502, headers: {"content-type": "application/json"}});
    }
  }
};

